function OverseaClubFeedCatAvatar:__init()
    self.skins = {}
    self.loaders = {}
    self.effects = {}

    self.bodyMesh = nil
    self.bodyTextureId = nil
    self.neckRoot = nil
    self.tailRoot = nil
    self.accessories = {}
    
    self.clickInterval = 1
    self.clickTime = 0
    
    self.events = CfUtils.EventsDecorated({
        [ClubUtils.EventName.FeedCat_LevelUp] = Bind(self, self.CatLevelUpEventHandle),
        [ClubUtils.EventName.FeedCat_PhaseUp] = Bind(self, self.CatPhaseUpEventHandle),
        [ClubUtils.EventName.FeedCat_FeedSuccess] = Bind(self, self.CatEatEventHandle),
    })
end

function OverseaClubFeedCatAvatar:__delete()
    self.catGo = nil
    for _,loader in pairs(self.loaders) do
        loader:Release()
    end
    self.loaders = {}
    
    CfUtils.EventsUndecorated(self.events)
end

function OverseaClubFeedCatAvatar:Init(root,phase,skins)
    self.rootGo = root
    self.phase = phase
    self.catRoot = KTool.CreateEmptyGameObject(root,CatRootName)
    local feedCatVcamNode = root.transform:Find('FeedCatVcam')
    self.feedCatVcam = CfUtils.GetOrAddComponent(feedCatVcamNode, CinemachineVirtualCamera)
    
    self:LoadCat(skins)
end

function OverseaClubFeedCatAvatar:LoadCat(skins)
    local model = self:GetModel(self.phase)
    ResourceModule.LoadGameObjectAsync(model,function(go)
        if not KTool.IsNull(go) then
            self.catGo = go
            local quickTap = KTool.GetOrAddComponent(go,QuickTapType)
            quickTap.onTap:AddListener(function()
                self:OnCatClick()
            end)
            self.feedCatVcam.LookAt = go.transform
            self.feedCatVcam.Follow = go.transform
            local body = go.transform:Find(PartTrPath.Body)
            local eyes = go.transform:Find(PartTrPath.Eyes)
            self.bodyMesh = body:GetComponent(typeof(SkinnedMeshRenderer))
            self.bodyTextureId = ShaderIds.Decorative
            --self.neckRoot = go.transform:Find(PartTrPath.Neck)
            --self.tailRoot = go.transform:Find(PartTrPath.Tail)
            ---@type UnityEngine.Transform
            local neckRoot = go.transform:Find(PartTrPath.NeckRoot)
            if isNotNull(neckRoot) then
                for i = 0, neckRoot.childCount - 1 do
                    local child = neckRoot:GetChild(i)
                    if child.name ~= "cat" and child.name ~= "eye" then
                        self.accessories[child.name] = child
                        CfUtils.SetActive(child,false)
                    end
                end    
            end
            local headWearRoot = go.transform:Find(PartTrPath.HeadWearRoot)
            if isNotNull(headWearRoot) then
                for i = 0, headWearRoot.childCount - 1 do
                    local child = headWearRoot:GetChild(i)
                    self.accessories[child.name] = child
                    CfUtils.SetActive(child,false)
                end    
            end
            
            self:ChangeSkin(Utils.SkinParts.Fur,skins[Utils.SkinParts.Fur])
            self:ChangeSkin(Utils.SkinParts.Neck,skins[Utils.SkinParts.Neck])
            self:ChangeSkin(Utils.SkinParts.Tail,skins[Utils.SkinParts.Tail])
        else
            printError("加载模型失败")
        end
    end,true,self.catRoot.transform)
end

function OverseaClubFeedCatAvatar:GetModel(phase)
    --TODO 暂时只开放两个等级
    --local phase = Utils.CalPetPhase(level)
    if phase > 3 then
        phase = 3
    end
    local vo = Utils.GetPhaseVo(phase)
    return string.format("Arts/Prefab/%d.prefab",vo.resourceId)
end

function OverseaClubFeedCatAvatar:GetSkinPath(id)
    local vo  = Utils.GetSkinVo(id)
    if vo == nil then
        printError("皮肤配置表中没有找到对应的皮肤id：%s",id)
        return
    end
    return vo.skinId
end

function OverseaClubFeedCatAvatar:GetSkinColor(id)
    local vo = Utils.GetSkinVo(id)
    if vo == nil then
        printError("皮肤配置表中没有找到对应的皮肤id：%s",id)
        return "#FFFFFF","#FFFFFF","#FFFFFF","#FFFFFF"
    end
    
    return vo.color1,vo.color2,vo.color3,vo.color4
end

function OverseaClubFeedCatAvatar:ChangeSkin(part,id)
    if id == nil or id == 0 then
        return
    end
    if self.skins[part] == nil or self.skins[part] ~= id then
        self.skins[part] = id
        if part == Utils.SkinParts.Fur then
            if self.phase == 1 then
                self:ChangeMaterial(self:GetSkinPath(id),self.bodyMesh)
            else
                self:ChangeTexture(self.bodyMesh,self.bodyTextureId,nil,self:GetSkinColor(id))
            end
        elseif part == Utils.SkinParts.Neck or part == Utils.SkinParts.Tail then
            --self:LoadResource(part,self:GetSkinPath(id),function(loader)
            --    self:ChangeAccessory(self.neckRoot,loader.ResultObject)
            --end)
            self:ChangeAccessory2(id,part)
        end
    end
end

function OverseaClubFeedCatAvatar:LoadResource(part,path,cb)
    if path == nil or string.isEmpty(path) then
        printError("资源路径为空")
        return
    end
    CoStart(function()
        local loader = ResourceModule.LoadBundleAsync(path,nil,true)
        while not loader.IsCompleted do
            CoYield()
        end
        if loader.IsSuccess then
            local oldLoader = self.loaders[part]
            if oldLoader then
                oldLoader:Release()
            end
            self.loaders[part] = loader
            cb(loader)
        else
            loader:Release()
            printError("加载资源失败")
        end
    end)
end

function OverseaClubFeedCatAvatar:ChangeMaterial(path,mesh)
    local index = -1
    if string.contains(path, "20039_body01") then
        index=0
    elseif string.contains(path, "20039_body02") then
        index=1
    elseif string.contains(path, "20039_body03") then
        index=2
    elseif string.contains(path, "20039_body04") then
        index=3
    end

    if index == -1 then
        return
    end
    local materialSwitcher = mesh:GetComponent(typeof(CS.Game.Native.Common.MaterialSwitcher))
    if materialSwitcher then
        materialSwitcher:SwitchMaterial(index)
    end
end

function OverseaClubFeedCatAvatar:ChangeTexture(mesh,textureId,texture,color1,color2,color3,color4)
    if texture then
        mesh.material:SetTexture(textureId,texture)    
    end
    if not string.isEmpty(color1) then
        mesh.material:SetColor(ShaderIds.Color1,XLuaUtils.HexToColor(color1))
    end
    if not string.isEmpty(color2) then
        mesh.material:SetColor(ShaderIds.Color2,XLuaUtils.HexToColor(color2))
    end
    if not string.isEmpty(color3) then
        mesh.material:SetColor(ShaderIds.Color3,XLuaUtils.HexToColor(color3))
    end
    if not string.isEmpty(color4) then
        mesh.material:SetColor(ShaderIds.Color4,XLuaUtils.HexToColor(color4))
    end
end

function OverseaClubFeedCatAvatar:ChangeAccessory(parent,goAsset)
    KTool.DestroyGameObjectChildren(parent)
    local go = GameObject.Instantiate(goAsset,parent)
    go.transform.localScale = Vector3.one;
    go.transform.localPosition = Vector3.zero;
    go.transform.localRotation = Quaternion.identity;
end

function OverseaClubFeedCatAvatar:ChangeAccessory2(id,part)
    local vo = Utils.GetSkinVo(id)
    if vo == nil then
        printError("皮肤配置表中没有找到对应的皮肤id：%s",id)
        return
    end
    local path = vo.skinId
    if string.isEmpty(path) then
        return
    end
    
    self:LoadResource(part,path,function(loader)
        local partName = vo.partName
        local oldName = part == Utils.SkinParts.Neck and self.neckName or self.tailName
        local go = self.accessories[oldName]
        CfUtils.SetActive(go,false)
        go = self.accessories[partName]
        CfUtils.SetActive(go,true)
        local material = loader.ResultObject
        if go and material then
            local mesh = go:GetComponent(typeof(SkinnedMeshRenderer))
            if isNull(mesh) then
                mesh = go:GetComponent(typeof(MeshRenderer))
            end
            mesh.material = material
        end
        if part == Utils.SkinParts.Neck then
            self.neckName = partName
        elseif part == Utils.SkinParts.Tail then
            self.tailName = partName
        end
    end)
end

function OverseaClubFeedCatAvatar:OnCatClick()
    local curTime = Time.time
    if curTime - self.clickTime < self.clickInterval then
        return
    end
    self.clickTime = curTime
    Events.Broadcast(ClubUtils.EventName.FeedCat_CatClick)
    CfUtils.PlayAnimator(self.catGo,AnimationName.Touch)
end

function OverseaClubFeedCatAvatar:CatLevelUpEventHandle(level)
    CfUtils.PlayAnimator(self.catGo,AnimationName.Grow1)
    self:PlayVfx(true)
    CoStart(function()
        CoYield(2)
        local vfxGo = self.effects[VfxPath.LevelUp]
        if vfxGo then
            CfUtils.SetActive(vfxGo,false)
        end
    end)
end

function OverseaClubFeedCatAvatar:CatPhaseUpEventHandle(phase)
    self.phase = phase
    self:SetVcamToCenter(true)
    local time = CfUtils.GetAnimatorTime(self.catGo,AnimationName.Grow2)
    CfUtils.PlayAnimator(self.catGo,AnimationName.Grow2)
    local preCat = self.catGo
    KTool.SetParent(preCat,self.rootGo)
    CfUtils.SetActive(self.catRoot,false)
    ---@type OverseaClubFeedCatMgr
    local Mgr = import("Game.UI.Club.FeedCat.OverseaClubFeedCatMgr"):GetInstance()
    self:LoadCat(Mgr.Server.dojo.petsFacade)
    self:PlayVfx(false)
    
    local tweenSe = DOTween.Sequence()
    UIRaycastBlocker:AddCondition("FeedCatAvatar_PhaseUp")
    tweenSe:Insert(time,preCat.transform:DOScale(VectorZero, Duration1))
    tweenSe:InsertCallback(time + Duration1 /2,function()
        GameObject.Destroy(preCat)
        CfUtils.SetActive(self.catRoot,true)
    end)
    
    tweenSe:OnComplete(function()
        UIRaycastBlocker:RemoveCondition("FeedCatAvatar_PhaseUp")
        local vfxGo = self.effects[VfxPath.PhaseUp]
        if vfxGo then
            CfUtils.SetActive(vfxGo,false)
        end
    end)
end

