function OverseaClubFeedCatAvatar:SetVcamToCenter(flag)
    local composer = self.feedCatVcam:GetCinemachineComponent(Aim)
    if flag then
        composer.m_ScreenX = 0.5
    else
        composer.m_ScreenX = 0.37
    
    end
    
end

function OverseaClubFeedCatAvatar:CatEatEventHandle()
    CfUtils.PlayAnimator(self.catGo,AnimationName.Eat)
end

function OverseaClubFeedCatAvatar:PlayVfx(isLevelUp)
    local path = isLevelUp and VfxPath.LevelUp or VfxPath.PhaseUp
    local vfxGo = self.effects[path]
    if vfxGo then
        CfUtils.SetActive(vfxGo,true)
    else
        ResourceModule.LoadGameObjectAsync(path,function(go)
            if not KTool.IsNull(go) then
                self.effects[path] = go
            end
        end,true,self.rootGo.transform)
    end
end

